const MOZA_MASCOT_B64 = 'data:image/png;base64,';
import { Hono } from 'hono';
import { cors } from 'hono/cors';

const getSiteKey = (c: any) => {
    if (!c.env.TURNSTILE_SECRET_KEY) {
        return '1x00000000000000000000AA'; // Dummy test key for local dev
    }
    return '0x4AAAAAADpuIfvXpUHXndxC';
};

import { secureHeaders } from 'hono/secure-headers';
import { setCookie, getCookie, deleteCookie } from 'hono/cookie';
import { createClient } from '@supabase/supabase-js';
import { jwtVerify, importJWK } from 'jose';

type Bindings = {
  ADMIN_EMAIL?: string;
  SUPABASE_URL: string;
  SUPABASE_ANON_KEY: string;
  GATEWAY_SECRET: string;
  SUPABASE_SERVICE_ROLE_KEY: string;
  SUPABASE_JWT_SECRET: string;
  TURNSTILE_SECRET_KEY: string;
  RAZORPAY_KEY_ID: string;
  RAZORPAY_KEY_SECRET: string;
  MERIPEHCHAAN_CLIENT_ID: string;
  MERIPEHCHAAN_CLIENT_SECRET: string;
  RATE_LIMITER: any;
  ZUUP_OAUTH: any;
};

const app = new Hono<{ Bindings: Bindings }>();

app.use('*', secureHeaders({
  crossOriginOpenerPolicy: false,
  contentSecurityPolicy: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'", "https://cdn.tailwindcss.com", "https://cdn.jsdelivr.net", "https://challenges.cloudflare.com", "https://checkout.razorpay.com", "https://static.cloudflareinsights.com"],
    styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
    fontSrc: ["'self'", "https://fonts.gstatic.com"],
    imgSrc: ["'self'", "data:", "https://raw.githubusercontent.com", "https://zuup.dev"],
    connectSrc: ["'self'", "https://auth.zuup.dev", "https://*.supabase.co", "https://challenges.cloudflare.com", "https://digilocker.meripehchaan.gov.in"],
    frameSrc: ["'self'", "https://challenges.cloudflare.com", "https://api.razorpay.com", "https://digilocker.meripehchaan.gov.in"],
  }
}));
app.use('/*', cors({
  origin: (origin) => {
    return origin || '*'; // Allow all origins to prevent CORS errors during integration
  },
  credentials: true,
  allowHeaders: ['Content-Type', 'Authorization', 'apikey', 'x-client-info', 'Prefer', 'Content-Profile', 'Accept-Profile', 'x-supabase-api-version'],
}));

app.get('/favicon.ico', (c) => c.body(null, 204));

const renderLoginUI = (error?: string, siteName: string = 'Zuup', defaultStep: string = 'login', turnstileSiteKey: string = '0x4AAAAAADpuIfvXpUHXndxC') => `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Zuup Auth | Sign In</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <script src="https://challenges.cloudflare.com/turnstile/v0/api.js" defer></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    fontFamily: { sans: ['Inter', 'sans-serif'] },
                    colors: {
                        bg: '#16171D',
                        card: '#1C1D26',
                        input: '#232530',
                        border: '#2C2E3A',
                        primary: '#F04F67',
                        primaryHover: '#D63D5C',
                        text: '#FFFFFF',
                        muted: '#8F91A3',
                    }
                }
            }
        }
    </script>
    <style>
        body { font-family: 'Inter', sans-serif; background-color: #16171D; color: white; }
        [x-cloak] { display: none !important; }
        /* Hide arrows on number inputs */
        input::-webkit-outer-spin-button, input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
        input[type=number] { -moz-appearance: textfield; }
    </style>
    <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>
</head>
<body class="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-y-auto">
    <!-- Floating Moza Mascot (Bottom Right) -->
    <img src="${MOZA_MASCOT_B64}" alt="Moza Mascot" class="fixed -bottom-10 -right-10 w-[450px] h-[450px] object-contain pointer-events-none opacity-40 z-0 rotate-[-10deg]" />

    <div class="mb-8 flex flex-col items-center relative z-10">
        <!-- Zuup Official Logo -->
        <img src="https://zuup.dev/lovable-uploads/b44b8051-6117-4b37-999d-014c4c33dd13.png" alt="Zuup" class="h-10 w-auto mb-4 scale-125 object-contain" />
        <h1 class="text-2xl font-bold text-white tracking-tight">Zuup <span class="text-primary font-normal">Auth</span></h1>
    </div>

    <!-- Login Card with Alpine -->
    <div x-data="authForm()" class="w-full max-w-[440px] bg-card rounded-[24px] border border-border p-8 md:p-10 shadow-2xl">
        
        <!-- Header -->
        <div class="text-center mb-8" x-show="step !== 'forgot_password'">
            <h2 class="text-[22px] font-bold text-white mb-2">Sign in to ${siteName}</h2>
            <p class="text-muted text-[15px]">Access all Zuup services with one account</p>
        </div>

        <div class="text-center mb-8" x-show="step === 'forgot_password'" x-cloak>
            <h2 class="text-[22px] font-bold text-white mb-2">Reset Password</h2>
            <p class="text-muted text-[15px]">We'll send you a secure link to reset it.</p>
        </div>

        ${error ? `<div class="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-xl mb-6 text-sm font-medium text-center">${error}</div>` : ''}
        
        <div x-show="errorMessage" x-text="errorMessage" x-cloak class="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-xl mb-6 text-sm font-medium text-center"></div>
        <div x-show="successMessage" x-text="successMessage" x-cloak class="bg-green-500/10 border border-green-500/20 text-[#33C481] p-3 rounded-xl mb-6 text-sm font-medium text-center"></div>

        <!-- Tabs -->
        <div class="flex bg-input border border-border rounded-xl p-1 mb-6" x-show="step === 'login' || step === 'otp_send'">
            <button @click="setTab('password')" type="button" :class="tab === 'password' ? 'bg-[#1C1D26] text-white shadow-sm' : 'text-muted hover:text-white'" class="flex-1 py-2 text-sm font-medium rounded-lg transition-colors">Password</button>
            <button @click="setTab('otp')" type="button" :class="tab === 'otp' ? 'bg-[#1C1D26] text-white shadow-sm' : 'text-muted hover:text-white'" class="flex-1 py-2 text-sm font-medium rounded-lg transition-colors">6-digit code</button>
        </div>

        <!-- FORM -->
        <form @submit.prevent="submitForm" class="flex flex-col gap-5">
            
            <!-- Email Input -->
            <div x-show="step !== 'otp_verify'">
                <input x-model="email" type="email" placeholder="jagrit@zuup.dev" required class="w-full px-4 py-3.5 bg-input border border-border rounded-xl text-white focus:outline-none focus:border-primary/50 transition-colors placeholder-muted text-[15px]" />
            </div>

            <!-- Active Email Display (for OTP Verify step) -->
            <div x-show="step === 'otp_verify'" x-cloak class="w-full px-4 py-3.5 bg-input border border-border rounded-xl flex justify-between items-center">
                <span class="text-white font-medium text-[15px]" x-text="email"></span>
                <button type="button" @click="step = 'otp_send'" class="text-primary text-sm font-medium hover:underline">Change</button>
            </div>

            <!-- Password Fields -->
            <div x-show="step === 'login'" x-cloak>
                <div class="flex justify-between items-center px-1 -mb-3 mt-1">
                    <label class="text-sm font-medium text-white">Password</label>
                    <button type="button" @click="step = 'forgot_password'" class="text-primary text-sm hover:underline">Forgot password?</button>
                </div>
                <div class="relative mt-4">
                    <input x-model="password" :type="showPassword ? 'text' : 'password'" placeholder="••••••••" class="w-full px-4 py-3.5 bg-input border border-border rounded-xl text-white focus:outline-none focus:border-primary/50 transition-colors placeholder-muted text-[15px] tracking-widest" :required="step === 'login'" />
                    <button type="button" @click="showPassword = !showPassword" class="absolute right-4 top-1/2 -translate-y-1/2 text-muted hover:text-white transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>
                    </button>
                </div>
            </div>

            <!-- PREMIUM 6-Digit OTP Fields -->
            <div x-show="step === 'otp_verify'" x-cloak>
                <div class="flex justify-between items-center px-1 -mb-3 mt-1">
                    <label class="text-sm font-medium text-white">6-digit code</label>
                </div>
                <div class="flex gap-2 justify-between mt-4">
                    <template x-for="(digit, index) in 6" :key="index">
                        <input type="text" maxlength="1" class="w-12 h-14 bg-input border border-border rounded-xl text-white text-center text-xl font-bold focus:outline-none focus:border-primary/50 transition-colors shadow-inner"
                            x-model="otpArray[index]"
                            @input="handleOtpInput($event, index)"
                            @keydown="handleOtpKeydown($event, index)"
                            @paste="handleOtpPaste($event)"
                            :id="'otp-' + index"
                        />
                    </template>
                </div>
            </div>

            <div x-show="step !== 'otp_verify'" class="cf-turnstile mt-2 flex justify-center" data-sitekey="${turnstileSiteKey}" data-theme="dark"></div>

            <button type="submit" :disabled="loading" class="w-full mt-3 px-4 py-3.5 bg-primary hover:bg-primaryHover disabled:opacity-50 text-white rounded-xl text-[16px] font-semibold transition-colors flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(240,79,103,0.15)]">
                <span x-show="loading" class="animate-spin w-4 h-4 border-2 border-white/30 border-t-white rounded-full"></span>
                <span x-show="!loading" class="flex items-center gap-2">
                    <svg x-show="step !== 'forgot_password'" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>
                    <svg x-show="step === 'forgot_password'" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 2L11 13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
                    <span x-text="buttonText"></span>
                </span>
            </button>
            
            <button type="button" x-show="step === 'forgot_password'" @click="setTab('password')" class="w-full mt-1 px-4 py-3 bg-transparent text-muted hover:text-white rounded-xl text-[15px] font-medium transition-colors">
                Back to Login
            </button>

            <!-- Passkeys Divider -->
            <div x-show="step === 'login'" class="flex items-center my-6">
                <div class="flex-grow border-t border-border"></div>
                <span class="px-4 text-xs font-semibold text-muted tracking-widest uppercase">Or</span>
                <div class="flex-grow border-t border-border"></div>
            </div>

            <!-- Sign in with Passkey Button -->
            <button type="button" x-show="step === 'login'" @click="signInWithPasskey" :disabled="loading" class="w-full px-4 py-3 bg-input hover:bg-[#2A2D3A] border border-border disabled:opacity-50 text-white rounded-xl text-[15px] font-semibold transition-colors flex items-center justify-center gap-3">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-primary"><path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3m-3.5 3.5L19 4"/></svg>
                Sign in with Passkey
            </button>
        </form>

        <div class="mt-8 text-center" x-show="step === 'login' || step === 'otp_send'">
            <p class="text-muted text-[15px]">Don't have an account? <a href="#" class="text-primary hover:underline">Sign up</a></p>
        </div>
    </div>

    <p class="text-muted text-[14px] mt-10">Centralized authentication for all Zuup services</p>

    <script>
        document.addEventListener('alpine:init', () => {
            Alpine.data('authForm', () => ({
                tab: 'password', 
                step: '${defaultStep}', // 'login', 'otp_send', 'otp_verify', 'forgot_password'
                email: '',
                password: '',
                otpArray: ['', '', '', '', '', ''],
                showPassword: false,
                loading: false,
                errorMessage: '',
                successMessage: '',
                redirectTo: new URLSearchParams(window.location.search).get('redirect_to') || 'https://zuup.dev/dashboard',
                clientId: new URLSearchParams(window.location.search).get('client_id') || '',
                redirectUri: new URLSearchParams(window.location.search).get('redirect_uri') || '',

                get buttonText() {
                    if (this.step === 'otp_send') return 'Send Code';
                    if (this.step === 'otp_verify') return 'Verify & Sign In';
                    if (this.step === 'forgot_password') return 'Send Reset Link';
                    return 'Sign In';
                },

                get otpCode() {
                    return this.otpArray.join('');
                },

                setTab(newTab) {
                    this.tab = newTab;
                    this.step = newTab === 'otp' ? 'otp_send' : 'login';
                    this.errorMessage = '';
                    this.successMessage = '';
                },

                handleOtpInput(e, index) {
                    const val = e.target.value;
                    if (val && index < 5) {
                        document.getElementById('otp-' + (index + 1)).focus();
                    }
                },
                handleOtpKeydown(e, index) {
                    if (e.key === 'Backspace' && !this.otpArray[index] && index > 0) {
                        document.getElementById('otp-' + (index - 1)).focus();
                    }
                },
                handleOtpPaste(e) {
                    e.preventDefault();
                    const pastedData = e.clipboardData.getData('text').slice(0, 6).split('');
                    pastedData.forEach((char, i) => {
                        if (i < 6) this.otpArray[i] = char;
                    });
                    if (pastedData.length > 0) {
                        const nextIndex = Math.min(pastedData.length, 5);
                        document.getElementById('otp-' + nextIndex).focus();
                    }
                },

                async submitForm() {
                    this.loading = true;
                    this.errorMessage = '';
                    this.successMessage = '';

                    try {
                        const turnstileToken = document.querySelector('[name="cf-turnstile-response"]')?.value;
                        if (this.step !== 'otp_verify' && !turnstileToken) {
                            throw new Error('Please complete the security check');
                        }

                        if (this.step === 'login') {
                            const res = await fetch('/api/login', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ email: this.email, password: this.password, turnstileToken, client_id: this.clientId, redirect_uri: this.redirectUri })
                            });
                            const data = await res.json();
                            if (!res.ok) throw new Error(data.error || 'Failed to login');
                            
                            if (data.redirect_to) {
                                window.location.href = data.redirect_to;
                            } else {
                                // Append token to URL to bypass cross-site cookie blockers
                                const url = new URL(this.redirectTo);
                                url.searchParams.set('token', data.token);
                                window.location.href = url.toString();
                            }
                        } 
                        else if (this.step === 'otp_send') {
                            const res = await fetch('/api/otp/send', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ email: this.email, turnstileToken })
                            });
                            const data = await res.json();
                            if (!res.ok) throw new Error(data.error || 'Failed to send code');
                            this.successMessage = 'Code sent! Check your email.';
                            this.step = 'otp_verify';
                            setTimeout(() => document.getElementById('otp-0')?.focus(), 100);
                        }
                        else if (this.step === 'otp_verify') {
                            if (this.otpCode.length !== 6) throw new Error('Please enter the 6-digit code');
                            const res = await fetch('/api/otp/verify', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ email: this.email, token: this.otpCode, client_id: this.clientId, redirect_uri: this.redirectUri })
                            });
                            const data = await res.json();
                            if (!res.ok) throw new Error(data.error || 'Invalid code');
                            
                            if (data.redirect_to) {
                                window.location.href = data.redirect_to;
                            } else {
                                // Append token to URL
                                const url = new URL(this.redirectTo);
                                url.hash = "access_token=" + data.token + "&refresh_token=" + (data.session?.refresh_token || "") + "&expires_in=" + (data.session?.expires_in || 3600) + "&token_type=bearer";
                                window.location.href = url.toString();
                            }
                        }
                        else if (this.step === 'forgot_password') {
                            const res = await fetch('/api/reset-password', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({ email: this.email, turnstileToken })
                            });
                            const data = await res.json();
                            if (!res.ok) throw new Error(data.error || 'Failed to send reset link');
                            this.successMessage = 'Password reset link sent to your email.';
                            this.email = '';
                        }
                    } catch (err) {
                        this.errorMessage = err.message || 'An error occurred';
                        if (window.turnstile && this.step !== 'otp_verify') turnstile.reset();
                    } finally {
                        this.loading = false;
                    }
                },

                async signInWithPasskey() {
                    this.loading = true;
                    this.errorMessage = '';
                    this.successMessage = '';
                    try {
                        // Initialize Supabase Client dynamically using the Zuup Proxy
                        const sbClient = supabase.createClient(window.location.origin, 'dummy_anon_key', {
                            auth: { experimental: { passkey: true } }
                        });
                        const { data, error } = await sbClient.auth.signInWithPasskey();
                        
                        if (error) throw error;
                        if (!data?.session) throw new Error("No session returned from passkey");

                        // Send the valid token to our backend to get the secure cookie and SSO redirect
                        const res = await fetch('/api/login/passkey', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ 
                                access_token: data.session.access_token,
                                client_id: this.clientId, 
                                redirect_uri: this.redirectUri 
                            })
                        });
                        
                        const backendData = await res.json();
                        if (!res.ok) throw new Error(backendData.error || 'Failed to establish secure session');
                        
                        if (backendData.redirect_to) {
                            window.location.href = backendData.redirect_to;
                        } else {
                            const url = new URL(this.redirectTo);
                            url.searchParams.set('token', backendData.token);
                            window.location.href = url.toString();
                        }
                    } catch (err) {
                        this.errorMessage = err.message || 'Passkey authentication failed';
                    } finally {
                        this.loading = false;
                    }
                }
            }));
        });
    </script>
</body>
</html>
`;

const renderUpdatePasswordUI = (error?: string, turnstileSiteKey: string = '0x4AAAAAADpuIfvXpUHXndxC') => `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Zuup Auth | Update Password</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <script src="https://challenges.cloudflare.com/turnstile/v0/api.js" defer></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    fontFamily: { sans: ['Inter', 'sans-serif'] },
                    colors: {
                        bg: '#16171D',
                        card: '#1C1D26',
                        input: '#232530',
                        border: '#2C2E3A',
                        primary: '#F04F67',
                        primaryHover: '#D63D5C',
                        text: '#FFFFFF',
                        muted: '#8F91A3',
                    }
                }
            }
        }
    </script>
    <style>
        body { font-family: 'Inter', sans-serif; background-color: #16171D; color: white; }
        [x-cloak] { display: none !important; }
    </style>
    <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
</head>
<body class="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-y-auto">
    <!-- Floating Moza Mascot (Bottom Right) -->
    <img src="${MOZA_MASCOT_B64}" class="fixed bottom-0 right-0 w-[500px] h-auto object-contain pointer-events-none z-0 opacity-90 hidden md:block" alt="Moza Mascot" />
    <div class="mb-8 flex flex-col items-center relative z-10">
        <h1 class="text-2xl font-bold text-white tracking-tight">Zuup <span class="text-primary font-normal">Auth</span></h1>
    </div>

    <div x-data="updateForm()" class="w-full max-w-[440px] bg-card rounded-[24px] border border-border p-8 md:p-10 shadow-2xl">
        <div class="text-center mb-8">
            <h2 class="text-[22px] font-bold text-white mb-2">Update Password</h2>
            <p class="text-muted text-[15px]">Enter your new password below</p>
        </div>

        <div x-show="errorMessage" x-text="errorMessage" x-cloak class="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-xl mb-6 text-sm font-medium text-center"></div>
        <div x-show="successMessage" x-text="successMessage" x-cloak class="bg-green-500/10 border border-green-500/20 text-[#33C481] p-3 rounded-xl mb-6 text-sm font-medium text-center"></div>

        <form @submit.prevent="submitForm" class="flex flex-col gap-5" x-show="!successMessage">
            <div class="relative mt-4">
                <input x-model="password" type="password" placeholder="New Password" required minlength="6" class="w-full px-4 py-3.5 bg-input border border-border rounded-xl text-white focus:outline-none focus:border-primary/50 transition-colors placeholder-muted text-[15px]" />
            </div>

            <div class="cf-turnstile mt-2 flex justify-center" data-sitekey="${turnstileSiteKey}" data-theme="dark"></div>

            <button type="submit" :disabled="loading" class="w-full mt-3 px-4 py-3.5 bg-primary hover:bg-primaryHover disabled:opacity-50 text-white rounded-xl text-[16px] font-semibold transition-colors flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(240,79,103,0.15)]">
                <span x-show="loading" class="animate-spin w-4 h-4 border-2 border-white/30 border-t-white rounded-full"></span>
                <span x-show="!loading">Update Password</span>
            </button>
        </form>
        
        <div class="mt-6 text-center">
             <a :href="redirectTo ? '/login?redirect_to=' + encodeURIComponent(redirectTo) : '/login'" class="text-primary hover:underline text-sm font-medium">Back to Login</a>
        </div>
    </div>

    <script>
        document.addEventListener('alpine:init', () => {
            Alpine.data('updateForm', () => ({
                password: '',
                loading: false,
                errorMessage: '',
                successMessage: '',
                accessToken: '',
                redirectTo: '',

                init() {
                    // Support Implicit Flow (hash) and PKCE Flow (query)
                    const hashParams = new URLSearchParams(window.location.hash.substring(1));
                    this.accessToken = hashParams.get('access_token');
                    
                    const queryParams = new URLSearchParams(window.location.search);
                    this.redirectTo = queryParams.get('redirect_to') || '';
                    this.code = queryParams.get('code');
                    
                    if (hashParams.get('error')) {
                        this.errorMessage = hashParams.get('error_description')?.replace(/\\+/g, ' ') || 'Failed to verify link. It may have expired.';
                    } else if (queryParams.get('error')) {
                        this.errorMessage = queryParams.get('error_description')?.replace(/\\+/g, ' ') || 'Failed to verify link. It may have expired.';
                    } else if (!this.accessToken && !this.code) {
                        this.errorMessage = 'Invalid or missing recovery token. Please request a new password reset link.';
                    }
                },

                async submitForm() {
                    if (!this.accessToken && !this.code) {
                        this.errorMessage = 'Missing token or code. Cannot update password.';
                        return;
                    }
                    
                    this.loading = true;
                    this.errorMessage = '';
                    
                    try {
                        const res = await fetch('/api/update-password', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ 
                                access_token: this.accessToken, 
                                code: this.code,
                                password: this.password, 
                                turnstileToken: document.querySelector('[name="cf-turnstile-response"]')?.value 
                            })
                        });
                        
                        const data = await res.json();
                        if (!res.ok) throw new Error(data.error || 'Failed to update password');
                        
                        this.successMessage = 'Password updated successfully! You can now log in.';
                        this.password = '';
                    } catch (err) {
                        this.errorMessage = err.message || 'An error occurred';
                    } finally {
                        this.loading = false;
                    }
                }
            }));
        });
    </script>
</body>
</html>
`;

app.get('/login', async (c) => {
  const error = c.req.query('error');
  const redirectTo = c.req.query('redirect_to');
  const clientId = c.req.query('client_id');
  const redirectUri = c.req.query('redirect_uri');
  let siteName = 'Zuup';
  
  if (redirectTo) {
    try {
      const url = new URL(redirectTo);
      siteName = url.hostname;
    } catch(e) {}
  }

  // Check for existing session to auto-login
  const token = getCookie(c, '__Secure-zuup_session');
  if (token && c.env.SUPABASE_JWT_SECRET) {
    try {
      let secretKey;
      if (c.env.SUPABASE_JWT_SECRET.trim().startsWith('{')) {
          const jwkData = JSON.parse(c.env.SUPABASE_JWT_SECRET);
          const jwk = jwkData.keys ? jwkData.keys[0] : jwkData;
          secretKey = await importJWK(jwk, jwk.alg || 'HS256');
      } else {
          secretKey = new TextEncoder().encode(c.env.SUPABASE_JWT_SECRET);
      }
      const { payload } = await jwtVerify(token, secretKey);
      
      // Valid token, we can auto-redirect
      const data = { session: { access_token: token }, user: payload };
      const responseData = await handleSSORedirect(c, clientId || '', redirectUri || '', data);
      
      if (responseData.redirect_to) {
        return c.redirect(responseData.redirect_to);
      } else if (redirectTo) {
        const url = new URL(redirectTo);
        url.searchParams.set('token', responseData.token || token);
        return c.redirect(url.toString());
      } else {
        return c.redirect(`https://zuup.dev/dashboard#access_token=${responseData.token || token}&refresh_token=${responseData.session?.refresh_token || ""}&expires_in=${responseData.session?.expires_in || 3600}&token_type=bearer`);
      }
    } catch (err: any) {
      // Invalid or expired token, just ignore and render login UI
    }
  }
  
  // Do NOT cache this page anymore since it depends on the user's cookies
  c.header('Cache-Control', 'private, no-cache, no-store, must-revalidate');
  return c.html(renderLoginUI(error, siteName, 'login', getSiteKey(c)));
});

app.get('/forgot-password', (c) => {
  const error = c.req.query('error');
  const redirectTo = c.req.query('redirect_to');
  let siteName = 'Zuup';
  if (redirectTo) { try { siteName = new URL(redirectTo).hostname; } catch(e) {} }
  c.header('Cache-Control', 'public, max-age=300');
  return c.html(renderLoginUI(error, siteName, 'forgot_password', getSiteKey(c)));
});

